  bech32VerifyChecksum,
} from './lib/bech32/checksum.mjs';
import { parseTest10Args } from './lib/cli/test10_args.mjs';
import { formatPythonBoolean, formatPythonList } from './lib/format/python_like.mjs';
import {
  PythonIntValueError,
  formatPythonIntTraceback,
  parseCommaSeparatedIntegers,
} from './lib/parse/python_ints.mjs';

export function main(argv = process.argv) {
  const args = parseTest10Args(argv);

  try {
    const data = parseCommaSeparatedIntegers(args.b);
    const checksum = bech32CreateChecksum(args.a, data);
    const combined = [...data, ...checksum];
    const isValid = bech32VerifyChecksum(args.a, combined);

    process.stdout.write(`${formatPythonList(checksum)}\n`);
    process.stdout.write(`${formatPythonBoolean(isValid)}\n`);
  } catch (error) {
    if (error instanceof PythonIntValueError) {
      process.stderr.write(`${formatPythonIntTraceback(error)}\n`);
      process.exit(1);
    }

    throw error;
  }
}

main();

